import usePopularTags from "../../hooks/usePopularTags";
import TagButton from "./TagButton";

function PopularTags() {
  const { tags, loading, error } = usePopularTags();

  return (
    <aside className="col-md-3">
      <div className="sidebar">
        <h6>Popular Tags</h6>
        <div className="tag-list">
          {loading ? (
            <p>Loading tags...</p>
          ) : error ? (
            <p>{error}</p>
          ) : tags.length > 0 ? (
            <TagButton tags={tags} />
          ) : (
            <p>Tags list not available</p>
          )}
        </div>
      </div>
    </aside>
  );
}

export default PopularTags;

function TagButton({ tags, limit = 50 }) {
  return tags.slice(0, limit).map((name) => (
    <button className="tag-pill tag-default" key={name} type="button">
      {name}
    </button>
  ));
}

export default TagButton;

import { useEffect, useState } from "react";
import getTags from "../services/getTags";

function usePopularTags() {
  const [tags, setTags] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let isMounted = true;

    async function loadTags() {
      try {
        const nextTags = await getTags();

        if (isMounted) {
          setTags(nextTags);
        }
      } catch (requestError) {
        if (isMounted) {
          setError("Tags list not available");
        }
        console.error(requestError);
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    }

    loadTags();

    return () => {
      isMounted = false;
    };
  }, []);

  return { tags, loading, error };
}

export default usePopularTags;
